<?php require __DIR__.'/_guard.php';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verify();db()->prepare('INSERT INTO expenses(title,category,amount,expense_date,notes,user_id) VALUES(?,?,?,?,?,?)')->execute([$_POST['title'],$_POST['category'],(float)$_POST['amount'],$_POST['expense_date'],$_POST['notes'],Auth::user()['id']]);} $rows=db()->query('SELECT * FROM expenses ORDER BY expense_date DESC,id DESC LIMIT 300')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/admin.css"></head><body><main><a href="/admin/">← Dashboard</a><h1>Expenses</h1><form method="post"><?=Security::field()?><input name="title" placeholder="Expense" required><input name="category" placeholder="Category"><input type="number" step=".01" name="amount" required><input type="date" name="expense_date" value="<?=date('Y-m-d')?>"><input name="notes" placeholder="Notes"><button>Save expense</button></form><?php foreach($rows as $r):?><p><?=e($r['expense_date'])?> · <?=e($r['title'])?> · <?=money($r['amount'])?></p><?php endforeach;?></main></body></html>